<?php declare(strict_types=1);namespace App\Controllers\Admin;use App\Core\DB;use App\Core\Request;use App\Core\Response;use App\Services\AdminUi;use App\Services\JobService;use App\Services\LicenseService;final class DashboardController extends AdminController{public function index(Request $e):Response{$V=LicenseService::stats();$E=DB::fetchAll('SELECT o.*, u.email, p.slug AS plan_slug FROM {{orders}} o JOIN {{users}} u ON u.id = o.user_id JOIN {{plans}} p ON p.id = o.plan_id ORDER BY o.id DESC LIMIT 8');$l=DB::fetchAll('SELECT a.*, l.license_key FROM {{activations}} a JOIN {{licenses}} l ON l.id = a.license_id ORDER BY a.id DESC LIMIT 8');$H=[];for($v=29;$v>=0;$v--){$M=gmdate('Y-m-d',time()-$v*86400);$H[$M]=0;}foreach(DB::fetchAll('SELECT paid_at, total FROM {{orders}} WHERE status = ? AND paid_at >= ?',['paid',gmdate('Y-m-d 00:00:00',time()-29*86400)])as $m){$P=substr((string)$m['paid_at'],0,10);if(isset($H[$P])){$H[$P]+=(int)$m['total'];}}$k=DB::fetchAll('SELECT p.slug, COUNT(*) AS n FROM {{licenses}} l JOIN {{plans}} p ON p.id = l.plan_id WHERE l.status = ? GROUP BY p.slug',['active']);$t=AdminUi::unreadMessages();$u=gmdate('Y-m-d H:i:s',time()-30*86400);$h=(int)DB::scalar('SELECT COUNT(*) FROM {{orders}} WHERE created_at >= ?',[$u]);$F=$h>0?(int)round(100*(int)$V['orders30']/$h):null;$q=(int)DB::scalar('SELECT COUNT(*) FROM {{licenses}} WHERE status = ? AND expires_at >= ? AND expires_at <= ?',['active',now(),gmdate('Y-m-d H:i:s',time()+7*86400)]);$r=['php'=>PHP_VERSION,'db'=>DB::driver(),'cron_last'=>\App\Core\Cron::lastRun(),'cron_late'=>AdminUi::cronLate(),'pending'=>JobService::pendingCount(),'failed'=>JobService::failedCount()];$Y=[['label'=>'Cron','level'=>$r['cron_late']?'bad':'ok'],['label'=>t('admin.health_queue').' · '.$r['pending'],'level'=>$r['failed']>0?'bad':($r['pending']>20?'warn':'ok')],['label'=>'PHP '.$r['php'],'level'=>'ok'],['label'=>(string)$r['db'],'level'=>'ok']];return $this->view('admin/dashboard',['stats'=>$V,'recentOrders'=>$E,'recentActivations'=>$l,'sales'=>$H,'byPlan'=>$k,'unread'=>$t,'paidRate'=>$F,'expiring'=>$q,'watch'=>AdminUi::watch(),'health'=>$r,'meta'=>['title'=>t('admin.dashboard'),'pills'=>$Y,'help'=>t('adm.dashboard_help')]]);}}